"use strict";(globalThis.webpackChunkgrc||=[]).push([[29412],{35635(e){e.exports=JSON.parse('{"citeKey":"devarajan2020hcompress","slug":"devarajan-2020-hcompress-70f7","title":"HCompress: Hierarchical Data Compression for Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","L. Logan","X.-H. Sun"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\'20), May 18-22, 2020","type":"Conference","entryType":"inproceedings","date":"May, 2020","year":2020,"era":"iit","month":5,"doi":"10.1109/ipdps47924.2020.00064","abstract":"Modern scientific applications read and write massive amounts of data through simulations, observations, and analysis. These applications spend the majority of their runtime in performing I/O. HPC storage solutions include fast node-local and shared storage resources to elevate applications from this bottleneck. Moreover, several middleware libraries (e.g., Hermes) are proposed to move data between these tiers transparently. Data reduction is another technique that reduces the amount of data produced and, hence, improve I/O performance. These two technologies, if used together, can benefit from each other. The effectiveness of data compression can be enhanced by selecting different compression algorithms according to the characteristics of the different tiers, and the multi-tiered hierarchy can benefit from extra capacity. In this paper, we design and implement HCompress, a hierarchical data compression library that can improve the application\'s performance by harmoniously leveraging both multi-tiered storage and data compression. We have developed a novel compression selection algorithm that facilitates the optimal matching of compression libraries to the tiered storage. Our evaluation shows that HCompress can improve scientific application\'s performance by 7x when compared to other state-of-the-art tiered storage solutions.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7-slides.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Compression","Data-Reduction","Dynamic Choice","Workflow Priorities","Library","Middleware","Engine","Hermes"],"_projectIds":["hermes","iris"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hermes","iris"],"memberAuthors":["devarajan-hariharan","kougkas-anthony","logan-luke","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"}]}')}}]);